import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

test.describe("sign out", () => {
  test("signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ request }) => {
    // Arrange: sign in so a session cookie exists on the client
    const login = await request.post("/api/auth/login", {
      data: { email: USERS.member, password: PASSWORD },
    });
    await expectStatus(login, 200);

    // Act
    const response = await request.post("/api/auth/logout");

    // Assert
    expect(response.status()).toBe(204);
    const cookie = response
      .headersArray()
      .find((h) => h.name.toLowerCase() === "set-cookie" && h.value.startsWith("session="));
    expect(cookie).toBeDefined();
    const value = cookie!.value.toLowerCase();
    // A cleared cookie has an empty value or an expiry in the past (max-age=0)
    expect(value.startsWith("session=;") || value.includes("max-age=0") || value.includes("expires=thu, 01 jan 1970")).toBe(true);
  });
});
